const {test}=require('node:test'),assert=require('node:assert/strict'),{verifyDeployment}=require('./verify-deployment');
const commit='a'.repeat(40),repository='VeamStudios/Test';
test('HTTP success without the exact deployed repository and commit is not release evidence',async()=>{for(const body of [{},{commit:'b'.repeat(40),repository},{commit,repository:'other/repo'}])await assert.rejects(verifyDeployment('https://example.com/version',commit,repository,async()=>({ok:true,json:async()=>body}),async()=>{}))});
test('verified deployment binds observed commit and repository, including delayed propagation',async()=>{let n=0;const r=await verifyDeployment('https://example.com/version',commit,repository,async()=>({ok:true,json:async()=>({commit:++n===1?'b'.repeat(40):commit,repository})}),async()=>{});assert.equal(r.reportedCommit,commit);assert.equal(n,2)});
test('HTML fallback and unavailable endpoints fail after bounded attempts',async()=>{let n=0;await assert.rejects(verifyDeployment('https://example.com/version',commit,repository,async()=>{n++;return{ok:true,json:async()=>{throw new Error('not JSON')}}},async()=>{}));assert.equal(n,3)});
test('hosting marker is inside the deployed public directory with cache bypass',()=>{const fs=require('node:fs'),os=require('node:os'),path=require('node:path'),{writeMarker}=require('../release-marker/write');const root=fs.mkdtempSync(path.join(os.tmpdir(),'release-marker-'));try{fs.writeFileSync(path.join(root,'firebase.json'),JSON.stringify({hosting:{public:'dist/browser'}}));writeMarker({root,repository,commit,config:'firebase.json'});assert.equal(JSON.parse(fs.readFileSync(path.join(root,'dist/browser/release-info.json'))).commit,commit);assert.equal(JSON.parse(fs.readFileSync(path.join(root,'firebase.json'))).hosting.headers[0].headers[0].value,'no-store, max-age=0')}finally{fs.rmSync(root,{recursive:true,force:true})}});

test('hosting predeploy recreates the marker after a build removes its directory',()=>{const fs=require('node:fs'),os=require('node:os'),path=require('node:path'),cp=require('node:child_process'),{writeMarker}=require('../release-marker/write');const root=fs.mkdtempSync(path.join(os.tmpdir(),'marker-hook-'));try{fs.writeFileSync(path.join(root,'firebase.json'),JSON.stringify({hosting:{public:'dist',ignore:['**/.*'],predeploy:['true']}}));writeMarker({root,repository,commit,config:'firebase.json',predeploy:true});fs.rmSync(path.join(root,'dist'),{recursive:true});const config=JSON.parse(fs.readFileSync(path.join(root,'firebase.json')));assert.equal(config.hosting.predeploy[0],'true');cp.execSync(config.hosting.predeploy[1],{cwd:root});assert.equal(JSON.parse(fs.readFileSync(path.join(root,'dist/release-info.json'))).commit,commit)}finally{fs.rmSync(root,{recursive:true,force:true})}});
